    if not md_file or not os.path.exists(md_file):
        print_err(f"ERROR {{book_file}}: Could not find file '{{md_file}}' for book chapter")
        sys.exit(0)

    generate_output(
        md_file, 
        config.get('lang', 'en'), 
        html_out=config.get('output.html'), 
        epub_out=config.get('output.epub'),
        title=config.get('title', '')
    )

    warnings = []
    errors = []

    if config.get('output.epub'):
        warnings.append("WARNING Could not run zip command, falling back to zip library")

    if config.get('output.pdf'):
        errors.append("ERROR Error rendering pdf: Error during temporary files editing: failed to run command 'xelatex'")

    if warnings or errors:
        print_err("WARNING Crowbook exited successfully, but the following errors occurred:")
        for w in warnings:
            print_err(w)
        for e in errors:
            print_err(e)

def parse_book(path):
    config = {{}}
    with open(path, 'r') as f:
        for line in f:
            line = line.strip()
            if line.startswith('#') or not line:
                continue
            if line.startswith('+ '):
                config['md_file'] = line[2:].strip()
                # Resolve relative to book dir if needed, simple approach:
                if not os.path.exists(config['md_file']):
                    d = os.path.dirname(path)
                    if d:
                        config['md_file'] = os.path.join(d, config['md_file'])
            elif ':' in line:
                k, v = line.split(':', 1)
                config[k.strip()] = v.strip()
    return config

def process_markdown(md_file, lang):
    with open(md_file, 'r') as f:
        lines = f.read().split('\\n')

    html_parts = []
    epub_parts = []
    para_count = 0
    link_count = 0
    in_para = False
    para_text = []

    def flush_para():
        nonlocal in_para, para_count, para_text
        if in_para:
            para_count += 1
            text = " ".join(para_text)
            html_parts.append(f'<p id = "para-{{para_count}}">{{text}}</p>')
            epub_parts.append(f'<p id = "para-{{para_count}}">{{text}}</p>')
            in_para = False
            para_text = []

    for line in lines:
        line = line.strip()
        if line.startswith('# '):
            flush_para()
            link_count += 1
            title = line[2:]
            if lang == 'fr':
                header = f'Chapitre {{link_count}}'
            elif lang == 'es':
                header = f'Capítulo {{link_count}}'
            else:
                header = f'Chapter {{link_count}}'
            html_parts.append(f"<h1 id = 'link-{{link_count}}'><span class = 'chapter-header'>{{header}}</span><br />{{title}}</h1>")
            epub_parts.append(f"<h1 id = 'link-{{link_count}}'><span class = 'chapter-header'>{{header}}</span><br />{{title}}</h1>")
        elif line.startswith('## '):
            flush_para()
            link_count += 1
            title = line[3:]
            html_parts.append(f"<h2 id = \\"link-{{link_count}}\\">{{title}}</h2>")
            epub_parts.append(f"<h2 id = \\"link-{{link_count}}\\">{{title}}</h2>")
        elif line == '':
            flush_para()
        else:
            line = re.sub(r'\\*\\*(.*?)\\*\\*', r'<b>\\1</b>', line)
            line = re.sub(r'\\*(.*?)\\*', r'<em>\\1</em>', line)
            in_para = True
            para_text.append(line)

    flush_para()
    return '\\n'.join(html_parts) + '\\n', '\\n'.join(epub_parts) + '\\n', link_count

def generate_output(md_file, lang, html_out=None, epub_out=None, title=""):
    html_content, epub_content, links = process_markdown(md_file, lang)

    if lang == 'fr':
        pre, post = fr_pre, fr_post
