    else:
        pre, post = en_pre, en_post
        epre, epost = en_epub_pre, en_epub_post
        epub_files = epub_en

    if title:
        # replace title in pre/post
        # It's a bit hardcoded because of base template, but we can regex it
        pre = re.sub(r'<title>.*?</title>', f'<title>{{title}}</title>', pre)
        pre = re.sub(r'<h1 id = "link-0" class="title" >.*?</h1>', f'<h1 id = "link-0" class="title" >{{title}}</h1>', pre)
        post = re.sub(r'"name": ".*?"', f'"name": "{{title}}"', post)

    if html_out:
